update public.master_catalog_parameters p
set reference_ranges=s.reference_ranges,
    source_references=coalesce(p.source_references,'[]'::jsonb) || s.source_references,
    reference_interval_status='local_verification_required',
    clinical_metadata=coalesce(p.clinical_metadata,'{}'::jsonb) ||
      jsonb_build_object('reference_interval_note',s.reference_note,
                         'reference_interval_source_type','external_source_suggested')
from source_data s
join public.master_catalog_tests t on t.master_code=s.master_code
where p.master_test_id=t.id and p.parameter_code=s.parameter_code
  and p.reference_ranges='[]'::jsonb
  and not exists (
    select 1 from jsonb_array_elements(coalesce(p.source_references,'[]'::jsonb)) existing_ref
    where existing_ref->>'id'=(s.source_references->0->>'id')
  );
